{
    "id": "spatial-use",
    "version": "1.0",
    "title": "Use within a country",
    "description": "Use allowed only in the given country",
    "content": {
        "@context": "http://www.w3.org/ns/odrl.jsonld",
        "@type": "Offer",
        "permission": [
            {
                "action": "use",
                "constraint": [
                    {
                        "leftOperand": "spatial",
                        "operator": "eq",
                        "rightOperand": "$country"
                    }
                ]
            }
        ]
    },
    "parameters": {
        "$country": {
            "dataType": "string"
        }
    }
}
